import java.util.Collections;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class XYSeries_addOrUpdate_TriageGen1Test {



    @Test
    public void testAddOrUpdate_AllowDuplicates_AddsAndReturnsNull() {
        // Constructor: XYSeries(Comparable key, boolean autoSort, boolean allowDuplicateXValues)
        XYSeries series = new XYSeries("Test", true, true);

        XYDataItem result = series.addOrUpdate(1.0, 10.0);

        assertNull("Should return null when duplicates are allowed", result);
        assertEquals(1, series.getItemCount());
        assertEquals(1.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(10.0, series.getY(0).doubleValue(), 0.001);

        // Add duplicate X
        series.addOrUpdate(1.0, 20.0);
        assertEquals(2, series.getItemCount());
    }








}

package org.jfree.data.xy;

import java.io.*;
