import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class XYSeries_addOrUpdate_TriageGen1Test {







    @Test
    public void testAddOrUpdate_NoDuplicates_AddNew_NoAutoSort() {
        // Constructor: XYSeries(Comparable key, boolean autoSort, boolean allowDuplicateXValues)
        XYSeries series = new XYSeries("Test", false, false);

        XYDataItem result = series.addOrUpdate(2.0, 20.0);

        assertNull(result);
        assertEquals(1, series.getItemCount());
        assertEquals(2.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(20.0, series.getY(0).doubleValue(), 0.001);

        // Add another item to check order (no auto sort)
        series.addOrUpdate(1.0, 10.0);
        assertEquals(2, series.getItemCount());
        assertEquals(2.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(1.0, series.getX(1).doubleValue(), 0.001);
    }




}

